from collections import deque

def alcanzable(grafo, origen, destino):
    visitados = {origen}
    cola = deque([origen])
    while cola:
        u = cola.popleft()
        if u == destino:
            return True
        for v in grafo.get(u, []):
            if v not in visitados:
                visitados.add(v)
                cola.append(v)
    return False

