import heapq

def dijkstra(grafo, origen):
    dist = {v: float('inf') for v in grafo}
    dist[origen] = 0
    previo = {}
    cola = [(0, origen)]
    while cola:
        d, u = heapq.heappop(cola)
        if d != dist[u]:
            continue
        for v, peso in grafo[u]:
            nd = d + peso
            if nd < dist[v]:
                dist[v] = nd
                previo[v] = u
                heapq.heappush(cola, (nd, v))
    return dist, previo

