from collections import deque

def edmonds_karp(cap, s, t):
    # cap[u][v] = capacidad residual; completar la búsqueda BFS,
    # hallar cuello de botella, actualizar aristas directas e inversas.
    residual = {u: dict(vs) for u, vs in cap.items()}
    flujo = 0
    while True:
        padre = {s: None}
        q = deque([s])
        while q and t not in padre:
            u = q.popleft()
            for v, c in residual[u].items():
                if c > 0 and v not in padre:
                    padre[v] = u
                    q.append(v)
        if t not in padre:
            return flujo
        cuello = float('inf')
        v = t
        while v != s:
            u = padre[v]
            cuello = min(cuello, residual[u][v])
            v = u
        v = t
        while v != s:
            u = padre[v]
            residual[u][v] -= cuello
            residual.setdefault(v, {})[u] = residual.get(v, {}).get(u, 0) + cuello
            v = u
        flujo += cuello

