from itertools import permutations

def automorfismo_no_trivial(A):
    n = len(A)
    identidad = tuple(range(n))
    for p in permutations(range(n)):
        if p == identidad:
            continue
        if all(A[i][j] == A[p[i]][p[j]]
               for i in range(n) for j in range(n)):
            return p
    return None

