def satisface(clauses, asignacion):
    # Una cláusula contiene literales: x o -x.
    for clausula in clauses:
        if not any((asignacion[abs(lit)] == (lit > 0))
                   for lit in clausula):
            return False
    return True

def sat_bruteforce(clauses, n):
    from itertools import product
    for bits in product([False, True], repeat=n):
        a = {i+1: bits[i] for i in range(n)}
        if satisface(clauses, a):
            return a
    return None

from itertools import permutations

def ruta_dentro(dist, limite):
    n = len(dist)
    for ruta in permutations(range(1, n)):
        camino = (0,) + ruta + (0,)
        costo = sum(dist[camino[i]][camino[i+1]]
                    for i in range(n))
        if costo <= limite:
            return camino, costo
    return None

