def vertex_cover(grafo, k):
    vertices = list(grafo)
    n = len(vertices)
    for mask in range(1 << n):
        if mask.bit_count() > k:
            continue
        elegidos = {vertices[i] for i in range(n)
                    if mask & (1 << i)}
        if all(u in elegidos or v in elegidos
               for u in grafo for v in grafo[u]):
            return elegidos
    return None

